def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        parts = lines[i].split()
        u, v = int(parts[0]), int(parts[1])
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    components = []

    def dfs(start):
        count = 0
        stack = [start]
        while stack:
            node = stack.pop()
            if not visited[node]:
                visited[node] = True
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return count

    for i in range(1, n + 1):
        if not visited[i]:
            size = dfs(i)
            components.append(size)

    def is_lucky(num):
        s = str(num)
        return all(c in '47' for c in s)

    def generate_lucky(max_n):
        if max_n == 0:
            return [0, 4, 7]
        lucky = [4, 7]
        q = [4, 7]
        while q:
            curr = q.pop(0)
            if curr * 10 + 4 <= max_n:
                q.append(curr * 10 + 4)
                lucky.append(curr * 10 + 4)
            if curr * 10 + 7 <= max_n:
                q.append(curr * 10 + 7)
                lucky.append(curr * 10 + 7)
        return lucky

    lucky_nums = generate_lucky(n)

    # Check if any existing component is lucky
    for size in components:
        if is_lucky(size):
            return '0\n'

    # Filter out lucky components
    comp_sizes = [s for s in components if not is_lucky(s)]

    if not comp_sizes:
        return '0\n'

    # DP to find minimum components to reach each lucky sum
    dp = {}
    dp[0] = 0

    for size in comp_sizes:
        for x in list(dp.keys()):
            new_sum = x + size
            if new_sum > n:
                continue
            if new_sum not in dp or dp[new_sum] > dp[x] + 1:
                dp[new_sum] = dp[x] + 1

    # Find minimum roads
    ans = float('inf')
    for lucky in lucky_nums:
        if lucky in dp:
            ans = min(ans, dp[lucky] - 1)

    if ans == float('inf'):
        return '-1\n'
    return f'{ans}\n'

