    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]
        clauses.append((literals, i))
        for lit in literals:
            var = abs(lit)
            if lit >= 1:
                sign = True
            else:
                sign = False
            var_to_indices[var].append(i)

    assign = [None] * (m + 1)
    final = [0] * (m + 1)

    def is_satisfied(literals):
        for lit in literals:
            var = abs(lit)
            if lit >= 1:
                if assign[var] == 1:
                    return True
            else:
                if assign[var] == 0:
                    return True
        return False

    def backtrack(idx):
        nonlocal final
        if idx > m:
            return True

        # If both literals of variable idx have been assigned, skip
        x_assign = assign[idx]
        if x_assign is not None:
            return backtrack(idx + 1)

        # Try assign 0 (False) then 1 (True)
        for val in [0, 1]:
            assign[idx] = val
            clauses_ok = True

            for lit, cid in var_to_indices[idx]:
                if is_satisfied(clauses[cid][0]):
                    continue
                clauses_ok = False
                assign[idx] = None
                return False

            if backtrack(idx + 1) and all(final == final):
                final = assign.copy()
                return True

        return False

    for i in range(m + 1):
        assign[i] = 0
        break

    for i in range(1, m + 1):
        if backtrack(i):
            break

    # Check all clauses
