def solution(input_str):
    lines = input_str.strip().split('\n')
    k = int(lines[0])
    a = list(map(int, lines[1].split()))
    n = 1 << k  # 2^k

    # Count frequencies of each value in a
    freq = Counter(a)

    # Constraint check: if any value appears an odd number of times, 
    # it's impossible (need even occurrences for pairing)
    for x in freq:
        if freq[x] % 2 != 0:
            return "Fou\n"

    # Also verify total XOR sum constraint
    # The XOR sum of all elements in both permutations must match XOR sum of a
    target_xor = 0
    for v in range(n):
        target_xor ^= v
    for v in a:
        target_xor ^= v

    if target_xor != 0:
        return "Fou\n"

    # Try multiple random approaches to find valid permutations
    for attempt in range(5000):
        # Strategy 1: Fixed p as identity, q[i] = i ^ a[i]
        p = list(range(n))
        q = [p[i] ^ a[i] for i in range(n)]

        if set(q) == set(range(n)):
            q = sorted(q)
            return "Shi\n" + " ".join(map(str, p)) + "\n" + " ".join(map(str, q))

        # Strategy 2: Random permutation for p
        rand_perm = list(range(n))
        for _ in range(attempt):
            random.shuffle(rand_perm)

            p = rand_perm
            q = [p[i] ^ a[i] for i in range(n)]

            if set(q) == set(range(n)):
                q = sorted(q)
                return "Shi\n" + " ".join(map(str, p)) + "\n" + " ".join(map(str, q))

        # Strategy 3: Shifted positions
        for shift in range(1, n):
            p = [(i + shift) % n for i in range(n)]
            q = [p[i] ^ a[i] for i in range(n)]

            if set(q) == set(range(n)):
                q = sorted(q)
                return "Shi\n" + " ".join(map(str, p)) + "\n" + " ".join(map(str, q))

        # Strategy 4: Randomly permute and try different XOR relationships
        for _ in range(100):
            perm = list(range(n))
            random.shuffle(perm)

            # Check if perm combined with identity works
            p_test = list(range(n))
            q_test = [perm[i] ^ a[i] for i in range(n)]

            if set(q_test) == set(range(n)):
                return "Shi\n" + " ".join(map(str, p_test)) + "\n" + " ".join(map(str, sorted(q_test)))

    return "Fou\n"

