            graph[u].append(v)
            graph[v].append(u)

        required = math.ceil(math.sqrt(n))

        # BFS-based cycle detection - try all starting vertices
        for start_node in range(1, n + 1):
            parent = {start_node: 0}
            order = [start_node]
            visited = [False] * (n + 1)
            checked = [False] * (n + 1)
            queue = deque([start_node])
            visited[start_node] = True
            found = False

            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    # Skip parent
                    if parent[v] == u:
                        continue

                    # If v is already visited and not parent, we FOUND a back edge!
                    if visited[v]:
                        # This is a back edge creating a cycle
                        cycle_path = []
                        curr = u
                        while curr != v:
                            cycle_path.append(curr)
                            curr = parent[curr]
                        cycle_path.append(v)
                        cycle_path.append(u)

                        if len(cycle_path) >= required:
                            return f"2\n{len(cycle_path)}\n{' '.join(map(str, cycle_path))}"

            # If no cycle found, build largest independent set from BFS tree
            independent_set = []
            for v in order:
                if not checked[v]:
                    passed = True
                    for existing in independent_set:
                        if v in graph[existing]:
                            passed = False
                            break

                    if passed:
                        independent_set.append(v)
                        checked[v] = True

            if len(independent_set) >= required:
                return f"1\n{required}\n{' '.join(map(str, independent_set[:required]))}"

    except:
