    # First check if graph has enough connectivity
    for i in range(1, n + 1):
        if dist[i] is None or dist[i][i] == INF:
            continue
        valid_path_exists = True
        break

    if not valid_path_exists:
        # Fallback - should not happen based on problem guarantee
        return '1 2 3 4'

    best_delta = -1
    best_cities = None

    # Try to find optimal path
    # We need to be careful about performance with large n
    c1_candidates = []
    c2_candidates = []

    # Find cities that have paths to other cities
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j and dist[i][j] != INF:
                if best_delta < 1:  # Minimize initial checks
