                    c2_candidates.append(j)

    # Efficient search
    visited_cities = set()

    for c1 in range(1, n + 1):
        # Skip if can't reach any other city
        hit = False
        for j in range(1, n + 1):
            if c1 != j and dist[c1][j] != INF:
                hit = True
                break
        if not hit:
            continue

        for c2 in range(1, n + 1):
            if c2 == c1 or c2 <= 0 or dist[c1][c2] == INF:
                continue

            for c3 in range(1, n + 1):
                if c3 in (c1, c2) or dist[c2][c3] == INF:
