class Dinic:
    def __init__(self, n):
        self.n = n
        self.capacity = {}
        self.graph = [[] for _ in range(n)]
        self.level = {}
        self.ptr = {}

    def add_edge(self, u, v, cap):
        self.capacity[(u, v)] = cap
        self.capacity[(v, u)] = 0
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = {i: -1 for i in range(self.n)}
        self.level[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for i, (v, cap, rev) in enumerate(self.graph[u]):
                if cap > 0 and v not in self.level:
                    self.level[v] = self.level[u] + 1
                    q.append(v)
        return t in self.level

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            self.ptr = {i: 0 for i in range(self.n)}
            while True:
                pushed = self.dfs(s, t, float('inf'), self.ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow

