    # Extended GCD for modular inverse (handles non-prime modulus)
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x, y = extended_gcd(b % a, a)
        return gcd, y - (b // a) * x, x

    def mod_inverse(a, m):
        if m == 1:
            return 0
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            return 0
        return x % m

