    inv_fact = [1] * (n + 1)
    inv_fact[n] = mod_inverse(fact[n], p)
    for i in range(n - 1, -1, -1):
        inv_fact[i] = (inv_fact[i+1] * (i + 1)) % p

    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % p * inv_fact[n-r] % p

    ans = 0
