                    for target in first_contacts:
                        if target != old_b:
                            break

                output_lines.append(f"{wire_idx + 1} {endpoint_to_change} {target}")

                # Update the wire for subsequent tracking
                if endpoint_to_change == old_a:
                    wires[wire_idx] = (target, old_b)
                else:
