def count_factors(x, p):
    """Count factors of p in x"""
    if x == 0:
        return 0
    c = 0
    while x > 0 and x % p == 0:
        c += 1
        x //= p
    return c

def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])
    matrix = [list(map(int, lines[i+1].split())) for i in range(1, n + 1)]

    # Precompute factors of 2 and 5 for each cell
    factors2 = [[count_factors(matrix[i][j], 2) for j in range(n)] for i in range(n)]
    factors5 = [[count_factors(matrix[i][j], 5) for j in range(n)] for i in range(n)]

    # dp[(i,j)] = set of (sum2, sum5, path_count) - non-dominated states
    from collections import defaultdict

    # Use dict mapping (sum2, sum5) -> set of parent choices for reconstruction
    dp = [defaultdict(set) for _ in range(n)]
    parent = [[None] * n for _ in range(n)]

    # Initialize start cell
    dp[0][0][(0, 0)] = 1

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            v2, v5 = factors2[i][j], factors5[i][j]

            # Collect all valid arrival states
            arrivals = []
            if i > 0:
                for (s2, s5), prev_count in dp[i-1][j].items():
                    new_count = prev_count + s2 + s5 + v2 + v5
                    arrivals.append((new_count, s2+v2, s5+v5))

            for (s2, s5), prev_count in dp[i][j-1].items():
                new_count = prev_count + s2 + s5 + v2 + v5
                arrivals.append((new_count, s2+v2, s5+v5))

            # Remove dominated states
            kept = []
            for (total, s2_i, s5_i) in arrivals:
                dominated = False
                for (prev_total, s2_j, s5_j) in kept:
                    if s2_i >= s2_j and s5_i >= s5_j:
                        dominated = True
                        break
                if not dominated:
                    kept.append((total, s2_i, s5_i))

            for (total, s2_i, s5_i) in kept:
                dp[i][j][(s2_i, s5_i)] = total
                # Store which parent led to this state
                if i > 0:
                    parent[i][j].add('U')
                if j > 0:
                    parent[i][j].add('L')

    # Find minimum trailing zeros at end
    best_pairs = []
    if dp[n-1][n-1]:
        for (s2, s5), score in dp[n-1][n-1].items():
            best_pairs.append((s2, s5, min(s2, s5)))

    if not best_pairs:
        return "0\n"

    # Choose the pair with minimum min(s2, s5)
    best_pair = min(best_pairs, key=lambda x: (x[2], x[0], x[1]))

    # Reconstruct path
    path = []
    i, j = n - 1, n - 1

    while i > 0 or j > 0:
        if parent[i][j] == 'U':
            path.append('D')
        elif parent[i][j] == 'L':
            path.append('R')
        i -= 1
        j -= 1

        # If we can go right
        if j >= i:
            path[-1] = 'R'
        else:
            path[-1] = 'D'

    path = ''.join(path[::-1])

    return f"{min(best_pair[0], best_pair[1])}\n{path}"

