                costs.append(0)
            else:
                costs.append(change_cost)

        # DP: dp0 = no removal segment yet, dp1 = removal segment started, dp2 = removal segment continued
        dp0 = [INF] * (n + 1)
        dp1 = [INF] * (n + 1)
        dp2 = [INF] * (n + 1)

        dp0[0] = 0

        for i in range(n):
            c = costs[i]
            remove_cost = segment_cost + (1 if dp0 > 0 else 0)

            # dp0[i+1]: don't start removal segment yet
            dp0[i + 1] = min(dp0[i] + c, dp1[i] + c)

            # dp1[i+1]: just started or continue removal segment
            if i == 0:
                dp1[i + 1] = min(c, dp0[i] + segment_cost)
            else:
                dp1[i + 1] = min(dp0[i] + remove_cost, dp2[i] + remove_cost)

            # dp2[i+1]: removal segment weighted option
            dp2[i + 1] = min(dp1[i] + remove_cost, dp2[i] + c)

        ans = min(ans, dp0[n], dp1[n+1], dp2[n+1])

