    # If both complements exist, we have flexibility
    # If only one exists, we're constrained

    # Key insight: we need to DFS and ensure consistency
    # Each number can be in set 0 (A) or set 1 (B)

    # For each number, track if it's been visited and what set it's in
    vis = [False] * n
    assignment = [None] * n

    def get_complement_a(val):
        return a - val

    def get_complement_b(val):
        return b - val

    def dfs(i, set_num, val, depth):
        if vis[i]:
            return assignment[i] == set_num

        vis[i] = True
        assignment[i] = set_num

        # If we're in set A (0), we need complement_a to be in A
        # If we're in set B (1), we need complement_b to be in B

        # Complement in set A should also be 0
        if val in val_to_idx:
            # Only check if the complement exists in our input
            pass

        # Check complement A
        comp_a = get_complement_a(val)
        if comp_a in val_to_idx:
            j = val_to_idx[comp_a]
            comp_a_set = assignment[j]
            if vis[j]:
                # If already visited, it must match our set
                if comp_a_set != set_num:
                    # Conflict!
                    return False
            else:
                # Recursively assign
                if not dfs(j, set_num, comp_a, depth + 1):
                    return False

        # Check complement B
        comp_b = get_complement_b(val)
        if comp_b in val_to_idx:
            j = val_to_idx[comp_b]
            comp_b_set = assignment[j]
            if vis[j]:
                if comp_b_set != set_num:
                    return False
            else:
                if not dfs(j, set_num, comp_b, depth + 1):
                    return False

        return True

    # Try assigning each unvisited number to set 0 or 1
    for i in range(n):
        if not vis[i]:
            # Try with set 0
            assignment[i] = 0
            vis[i] = True

            # Check if complement in A needs to be 0
            comp_a = get_complement_a(p[i])
            if comp_a in val_to_idx:
