def solution(input_str):
    n, l, r = map(int, input_str.strip().split())

    if n == 1:
        return f"{r - l + 1}\n"
    elif n == 2:
        return f"{(r - l + 1) * (r - l)}\n"

    # For n >= 3
    res = 0

    for q in range(2, r + 1):
        # Compute q^(n-1) - if exceeds r, no solutions for this q
        pow_q = 1
        for _ in range(n - 1):
            pow_q *= q
            if pow_q > r:
                break

        if pow_q > r:
            continue

        # max_p: p^(n-1) * q^(n-1) / q^(n-1) = p^(n-1) * q^(n-1) <= r * q^(n-1)
        # Simplified: p^(n-1) <= r is a key constraint
        max_p_limit = r // q

        for p in range(q + 1, max_p_limit + 1):
            if gcd(p, q) != 1:
                continue

            # Compute p^(n-1)
            pow_p = 1
            for _ in range(n - 1):
                pow_p *= p
                if pow_p > r:
                    break

            if pow_p > r:
                continue

            # Find valid a1 values:
            # a1 must be divisible by q^(n-1)
            # a1 * p^(n-1) / q^(n-1) <= r means a1 <= r * q^(n-1) / p^(n-1)
            min_start = pow_q
            max_start = (r * pow_q) // pow_p

            if max_start >= min_start:
                res += (max_start // pow_q)

    # Multiply by 2 for symmetric d < 1 cases
    return f"{res * 2}\n"

