    paid_buildings = [(v, c) for v, c in buildings if c > 0]

    # Sort paid buildings by efficiency (v/c descending)
    paid_buildings.sort(key=lambda x: x[0] / x[1], reverse=True)

    # Function to check if we can reach s cookies in 'time' seconds
    def can_reach(time):
        if time == 0:
            return False

        cookies = 0
        used = set()

        for t in range(time):
            # First, buy any free buildings we haven't bought
            for v, c in free_buildings:
                if not used:
                    used.add((v, c))
            if (0, 0) in used:
                break

            # Try to buy the best available building
            best_v = 0
            best_c = 0

            # Check all buildings
            for v, c in buildings:
                if (v, c) not in used and c <= cookies:
                    if v > best_v or (v == best_v and c < best_c):
                        best_v = v
                        best_c = c

            if best_c > 0:
                cookies -= best_c
                used.add((best_v, best_c))

            # Use best building for this second
            if best_c > 0:
                cookies += best_v
            else:
                cookies += 1  # Click manually

        return cookies >= s

    # Binary search for minimum time
    left, right = 0, s
    while left < right:
        mid = (left + right) // 2
        if can_reach(mid):
            right = mid
        else:
            left = mid + 1

    return str(left)


