import itertools

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    numbers = []
    for i in range(1, n+1):
        parts = lines[i].split()
        s, m = parts[0], int(parts[1])
        numbers.append((s, m))

    # Collect all unique prefixes from all numbers
    prefix_set = set()
    for s, m in numbers:
        for i in range(1, len(s) + 1):
            prefix_set.add(s[:i])

    # Sort by length (descending) for priority when same length
    prefix_list = sorted(list(prefix_set), key=lambda p: (-len(p), p))
    num_prefixes = len(prefix_list)

    # If k=0, no speed dial benefits either way
    if k == 0:
        return str(sum(len(s) * m for s, m in numbers))

    # When k >= number of unique prefixes, use all prefixes
    if num_prefixes < k:
        total = 0
        for s, m in numbers:
            long_p = max((len(p) for p in prefix_list if s.startswith(p)), default=0)
            total += (len(s) - long_p) * m
        return str(total)

    # Enumerate all k-combinations of prefixes to find minimum
    best = float('inf')
    for subset in itertools.combinations(prefix_list, k):
        total = 0
        for s, m in numbers:
            # Find longest prefix from subset that matches s
            long_p = max((len(p) for p in subset if s.startswith(p)), default=0)
            total += (len(s) - long_p) * m
        best = min(best, total)

    return str(best)
